import os
import sys
import subprocess
import json

def extract_pdf_text(filepath, max_chars=2000):
    try:
        result = subprocess.run(['pdftotext', '-l', '2', filepath, '-'], 
                              capture_output=True, text=True, timeout=30)
        text = result.stdout[:max_chars]
        return text
    except Exception as e:
        return f"ERROR: {e}"

def extract_docx_text(filepath, max_chars=2000):
    try:
        from docx import Document
        doc = Document(filepath)
        text = '\n'.join([p.text for p in doc.paragraphs[:30]])
        return text[:max_chars]
    except Exception as e:
        return f"ERROR: {e}"

def extract_pptx_text(filepath, max_chars=2000):
    try:
        from pptx import Presentation
        prs = Presentation(filepath)
        text = []
        for slide in prs.slides[:10]:
            for shape in slide.shapes:
                if hasattr(shape, "text"):
                    text.append(shape.text)
        return '\n'.join(text)[:max_chars]
    except Exception as e:
        return f"ERROR: {e}"

basedir = '/root/papers/all'
files = sorted(os.listdir(basedir))
results = {}

for f in files:
    fp = os.path.join(basedir, f)
    if f.endswith('.pdf'):
        results[f] = extract_pdf_text(fp)
    elif f.endswith('.docx'):
        results[f] = extract_docx_text(fp)
    elif f.endswith('.pptx'):
        results[f] = extract_pptx_text(fp)
    else:
        results[f] = "UNKNOWN FORMAT"

# Output results
for fname, text in results.items():
    print(f"===FILE: {fname}===")
    # Print first 800 chars for classification
    print(text[:800])
    print()

